shell_commands.command:
cd /testbed && git apply <<'PATCH'
diff --git a/tokio/tests/sync_broadcast.rs b/tokio/tests/sync_broadcast.rs
--- a/tokio/tests/sync_broadcast.rs
+++ b/tokio/tests/sync_broadcast.rs
@@ -503,6 +503,40 @@ fn resubscribe_points_to_tail() {
     assert_empty!(rx_resub);
 }

+#[test]
+fn resubscribe_closed() {
+    let (tx, rx) = broadcast::channel::<()>(4);
+    drop(tx);
+
+    let mut rx_try = rx.resubscribe();
+    let mut rx_recv = rx.resubscribe();
+    drop(rx);
+
+    assert_closed!(rx_try.try_recv());
+
+    let mut recv = task::spawn(rx_recv.recv());
+    assert!(is_closed(assert_ready_err!(recv.poll())));
+}
+
+#[test]
+fn resubscribe_closed_with_pending_messages() {
+    let (tx, mut rx) = broadcast::channel(1);
+    assert_ok!(tx.send(1));
+    assert_ok!(tx.send(2));
+    drop(tx);
+
+    let mut rx_resub = rx.resubscribe();
+    assert_closed!(rx_resub.try_recv());
+    drop(rx_resub);
+
+    assert_lagged!(rx.try_recv(), 1);
+    assert_eq!(assert_recv!(rx), 2);
+    assert_closed!(rx.try_recv());
+}
+
 #[test]
 fn resubscribe_lagged() {
     let (tx, mut rx) = broadcast::channel(1);
PATCH
cargo test --offline --test sync_broadcast --features full resubscribe_closed

